import React from 'react';
import { useNavigate } from 'react-router-dom';
import {
  AppBar,
  Box,
  Button,
  Chip,
  Container,
  Stack,
  Toolbar,
  Typography,
} from '@mui/material';
import { Logout as LogoutIcon } from '@mui/icons-material';
import BrandLogoMark from '../BrandLogoMark';
import {
  getPartnerPortalPartner,
  getPartnerPortalUser,
} from '../../utils/partnerPortalSession';
import { useRegistration } from '../../context/RegistrationContext';

interface PartnerPortalLayoutProps {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}

const PartnerPortalLayout: React.FC<PartnerPortalLayoutProps> = ({
  title,
  subtitle,
  children,
}) => {
  const navigate = useNavigate();
  const { logout } = useRegistration();
  const user = getPartnerPortalUser();
  const partner = getPartnerPortalPartner();

  const displayName = [user?.profile?.firstName, user?.profile?.lastName]
    .filter(Boolean)
    .join(' ')
    .trim();

  const handleLogout = () => {
    logout({ redirectTo: '/login' });
  };

  return (
    <Box sx={{ minHeight: '100vh', bgcolor: 'grey.100' }}>
      <AppBar position="static" color="default" elevation={1}>
        <Toolbar sx={{ gap: 2, flexWrap: 'wrap', py: 1 }}>
          <BrandLogoMark width={160} />
          <Box sx={{ flexGrow: 1, minWidth: 180 }}>
            <Typography variant="subtitle2" color="text.secondary">
              Partner portal
            </Typography>
            <Typography variant="body2" sx={{ fontWeight: 600 }}>
              {partner?.name || displayName || user?.email}
            </Typography>
          </Box>
          <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
            {partner?.apiKeyMasked && (
              <Chip size="small" variant="outlined" label={partner.apiKeyMasked} />
            )}
            <Button size="small" color="inherit" onClick={() => navigate('/partners/api-documentation')}>
              API docs
            </Button>
            <Button
              size="small"
              variant="outlined"
              startIcon={<LogoutIcon />}
              onClick={handleLogout}
            >
              Sign out
            </Button>
          </Stack>
        </Toolbar>
      </AppBar>

      <Container maxWidth="xl" sx={{ py: 3 }}>
        <Typography variant="h4" component="h1" gutterBottom>
          {title}
        </Typography>
        {subtitle && (
          <Typography variant="body1" color="text.secondary" sx={{ mb: 3, maxWidth: 900 }}>
            {subtitle}
          </Typography>
        )}
        {children}
      </Container>
    </Box>
  );
};

export default PartnerPortalLayout;
