import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  CircularProgress,
  LinearProgress,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material';
import ScrollableTableContainer from '../shared/ScrollableTableContainer';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';
import FootprintStoryPanel from '../shared/FootprintStoryPanel';

const authHeaders = () => ({ Authorization: `Bearer ${localStorage.getItem('token')}` });

type CohortCarbon = {
  carbonScore?: number;
  totalCO2Emissions?: number;
  assessmentStatus?: string;
  scopes?: { scope1?: number; scope2?: number; scope3?: number };
};

type CohortRow = {
  id?: string;
  companyName?: string;
  industry?: string;
  status?: string;
  carbon?: CohortCarbon | null;
};

type ReportRow = {
  type?: string;
  status?: string;
  score?: number | null;
  blockedReasons?: string[];
};

const PartnerMsmeCohortPanel: React.FC = () => {
  const [items, setItems] = useState<CohortRow[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [detailLoading, setDetailLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [reports, setReports] = useState<ReportRow[]>([]);
  const [indiaScore, setIndiaScore] = useState<number | null>(null);
  const [exportScore, setExportScore] = useState<number | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await axios.get(buildApiUrl('/partner-account/msmes'), {
        headers: authHeaders(),
        params: search ? { search } : {},
      });
      setItems((res.data?.data?.items || []) as CohortRow[]);
    } catch (e) {
      setError(axios.isAxiosError(e) ? e.response?.data?.message || e.message : 'Failed to load cohort');
      setItems([]);
    } finally {
      setLoading(false);
    }
  }, [search]);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    if (selectedId && items.length > 0 && !items.some((row) => String(row.id) === selectedId)) {
      setSelectedId(null);
    }
  }, [items, selectedId]);

  useEffect(() => {
    if (!selectedId) {
      setReports([]);
      setIndiaScore(null);
      setExportScore(null);
      return;
    }
    let cancelled = false;
    const loadDetail = async () => {
      setDetailLoading(true);
      try {
        const [carbonRes, reportsRes] = await Promise.all([
          axios.get(buildApiUrl(`/partner-account/msmes/${selectedId}/carbon-summary`), {
            headers: authHeaders(),
          }),
          axios.get(buildApiUrl(`/partner-account/msmes/${selectedId}/reports-overview`), {
            headers: authHeaders(),
          }),
        ]);
        if (cancelled) return;
        const carbonMsme = carbonRes.data?.data?.msme as CohortRow | undefined;
        if (carbonMsme) {
          setItems((prev) => prev.map((row) => (
            String(row.id) === selectedId ? { ...row, carbon: carbonMsme.carbon || row.carbon } : row
          )));
        }
        setReports(reportsRes.data?.data?.reports || []);
        setIndiaScore(reportsRes.data?.data?.indiaReadiness?.score ?? null);
        setExportScore(reportsRes.data?.data?.exportReadiness?.score ?? null);
      } catch (e) {
        if (!cancelled) {
          setError(axios.isAxiosError(e) ? e.response?.data?.message || e.message : 'Failed to load MSME detail');
        }
      } finally {
        if (!cancelled) setDetailLoading(false);
      }
    };
    void loadDetail();
    return () => { cancelled = true; };
  }, [selectedId]);

  const selected = useMemo(
    () => items.find((row) => String(row.id) === selectedId) || null,
    [items, selectedId]
  );

  return (
    <Box>
      <Stack direction="row" spacing={1} sx={{ mb: 2 }}>
        <TextField size="small" placeholder="Search company" value={search} onChange={(e) => setSearch(e.target.value)} />
        <Button variant="contained" onClick={load}>Search</Button>
      </Stack>
      {error ? <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>{error}</Alert> : null}

      {selected ? (
        <Box sx={{ mb: 3 }}>
          <Typography variant="subtitle2" color="text.secondary" sx={{ mb: 1 }}>
            Selected cohort member: {selected.companyName}
          </Typography>
          <FootprintStoryPanel
            title="Client footprint story"
            totalKg={Number(selected.carbon?.totalCO2Emissions) || 0}
            scope1Kg={Number(selected.carbon?.scopes?.scope1) || 0}
            scope2Kg={Number(selected.carbon?.scopes?.scope2) || 0}
            scope3Kg={Number(selected.carbon?.scopes?.scope3) || 0}
            summary="Read-only view of this MSME’s latest assessment for partner review."
            emptySummary="This MSME has not completed a carbon assessment yet."
          />

          <Box sx={{ p: 2, border: '1px solid', borderColor: 'divider', borderRadius: 1, mb: 1 }}>
            <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 1 }}>
              <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
                API-depth readiness
              </Typography>
              <Button size="small" onClick={() => setSelectedId(null)}>Clear</Button>
            </Stack>
            {detailLoading ? <LinearProgress sx={{ mb: 2 }} /> : null}
            <Stack direction="row" spacing={1} useFlexGap flexWrap="wrap" sx={{ mb: 1.5 }}>
              <Chip size="small" color="primary" variant="outlined" label={`India ${indiaScore != null ? `${Math.round(indiaScore)}%` : '—'}`} />
              <Chip size="small" color="secondary" variant="outlined" label={`Export ${exportScore != null ? `${Math.round(exportScore)}%` : '—'}`} />
            </Stack>
            <ScrollableTableContainer>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>Framework</TableCell>
                    <TableCell>Status</TableCell>
                    <TableCell>Score</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {reports.slice(0, 8).map((report) => (
                    <TableRow key={report.type}>
                      <TableCell>{report.type}</TableCell>
                      <TableCell><Chip size="small" label={report.status || '—'} /></TableCell>
                      <TableCell>{report.score != null ? `${Math.round(Number(report.score))}%` : '—'}</TableCell>
                    </TableRow>
                  ))}
                  {reports.length === 0 && !detailLoading ? (
                    <TableRow>
                      <TableCell colSpan={3}>No readiness overview yet for this MSME.</TableCell>
                    </TableRow>
                  ) : null}
                </TableBody>
              </Table>
            </ScrollableTableContainer>
          </Box>
        </Box>
      ) : (
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
          Select a company to open its footprint story and reports overview.
        </Typography>
      )}

      {loading ? <CircularProgress /> : (
        <ScrollableTableContainer>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell>Company</TableCell>
                <TableCell>Industry</TableCell>
                <TableCell>Status</TableCell>
                <TableCell>Carbon</TableCell>
                <TableCell>tCO₂e</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {items.map((row) => {
                const id = String(row.id);
                const totalKg = Number(row.carbon?.totalCO2Emissions) || 0;
                return (
                  <TableRow
                    key={id}
                    hover
                    selected={selectedId === id}
                    onClick={() => setSelectedId(id)}
                    sx={{ cursor: 'pointer' }}
                  >
                    <TableCell>{String(row.companyName || '—')}</TableCell>
                    <TableCell>{String(row.industry || '—')}</TableCell>
                    <TableCell><Chip size="small" label={String(row.status || '—')} /></TableCell>
                    <TableCell>{row.carbon?.carbonScore ?? '—'}</TableCell>
                    <TableCell>{totalKg > 0 ? (totalKg / 1000).toFixed(2) : '—'}</TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
        </ScrollableTableContainer>
      )}
    </Box>
  );
};

export default PartnerMsmeCohortPanel;
